TP.register({id:"lp2-gtk",lp:2,grade:"TK",mode:"curriculum",checks:1,nextGrade:"Kindergarten",build(E){const F=E.F;const X={apple:"apple",gapple:"apple",pear:"pear",bee:"bee",honey:"honey",flower:"purpleFlower",tree:"tree",ladybug:"ladybug",cake:"cake",leaf:"leaf",duck:"duck",hen:"hen",sheep:"sheep",fox:"fox",pig:"pig",bird:"bluebird",deer:"deer",chick:"chick",butterfly:"butterfly",tractor:"tractor",run:"run",bike:"bike",hand:"hand",pencil:"pencil",bus:"bus",cup:"cocoa",pan:"pan",dog:"dog"};const COL={red:"#EC6358",blue:"#6FA3DE",green:"#7CC18C",yellow:"#FBD873",orange:"#F2A24A"};const INK="#6B4A3C";const FACE=window.TP_ICON_FACE||(()=>"");const faceAt=(x,y,k,sp,mw)=>`<g transform="translate(${x},${y}) scale(${k})">${FACE(0,0,sp,mw)}</g>`;const svg=(w,h,body,alt,dw)=>`<svg viewBox="0 0 ${w} ${h}" width="${dw||w}" role="img" aria-label="${alt||"Picture"}">${body}</svg>`;const em=(x,y,e,s)=>F.picXY(x,y,e,s)||`<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${e}</text>`;const actPic=(x,y,n,s)=>{const d=window.TP_ACT[n],h=s*1.2,w=Math.min(h*d[1]/d[2],s*1.45);const hh=w*d[2]/d[1];return`<image href="data:image/webp;base64,${d[0]}" x="${x-w/2}" y="${y-hh/2}" width="${w}" height="${hh}"/>`};const put=(x,y,e,s)=>typeof e==="string"&&e.slice(0,4)==="ACT:"?actPic(x,y,e.slice(4),s):e==="BASKET"?basketIcon(x,y,s):em(x,y,e,s);const frame=(w,h,fill)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${fill||"var(--surface)"}" stroke="var(--line)" stroke-width="4"/>`;const col=(...a)=>`<div class="figure" style="flex-direction:column;align-items:center;gap:12px">${a.join("")}</div>`;const tag=(x,y,t)=>`<circle cx="${x}" cy="${y}" r="20" fill="var(--sea-soft)" stroke="var(--line)" stroke-width="2"/><text x="${x}" y="${y+1}" font-size="22" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${t}</text>`;const grass=(w,h,top)=>`<path d="M5 ${top} Q${w/2} ${top-22} ${w-5} ${top} V${h-30} Q${w-5} ${h-5} ${w-30} ${h-5} H30 Q5 ${h-5} 5 ${h-30} Z" fill="#7DB86A" opacity=".55"/>`;function cards(list,o){o=o||{};const c=o.cell||190,s=o.size||110,gap=16,extra=o.num?42:0,w=list.length*(c+gap)-gap+6,h=c+extra+6;let b="";list.forEach((e,i)=>{const x=3+i*(c+gap);b+=`<rect x="${x}" y="3" width="${c}" height="${c}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`+put(x+c/2,3+c/2,e,s);if(o.num)b+=`<text x="${x+c/2}" y="${c+34}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">${i+1}</text>`});return svg(w,h,b,o.alt||"Picture cards")}function countPanel(groups,alt){const w=940,lh=76;let y=12,b="";groups.forEach((g,gi)=>{const e=g[0],n=g[1],per=g[2],cell=g[3],size=g[4],h=Math.ceil(n/per)*lh;if(gi)b+=`<path d="M22 ${y} H${w-22}" stroke="var(--line)" stroke-width="3"/>`;b+=tag(48,y+8+h/2,gi+1);for(let i=0;i<n;i++)b+=put(96+i%per*cell+cell/2,y+8+Math.floor(i/per)*lh+lh/2,e,size);y+=h+16});return svg(w,y+4,frame(w,y+4)+b,alt)}function scatter(t,e,n,seed,alt,dw){const W=440,H=300;let x=seed;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};const slots=[];for(let r=0;r<3;r++)for(let c=0;c<5;c++)slots.push([c,r]);for(let i=slots.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));const s=slots[i];slots[i]=slots[j];slots[j]=s}let b=frame(W,H)+(t?tag(34,34,t):"");slots.slice(0,n).forEach(s=>{b+=put(Math.round(92+s[0]*70+(rnd()*20-10)),Math.round(66+s[1]*86+(rnd()*18-9)),e,50)});return svg(W,H,b,alt,dw)}const grid2=(...a)=>`<div class="figure" style="display:grid;grid-template-columns:auto auto;gap:12px;justify-content:center">${a.join("")}</div>`;function cmpPanel(t,eA,nA,cellA,eB,nB,cellB,alt){const w=880,h=176;let b=frame(w,h)+tag(42,40,t);for(let i=0;i<nA;i++)b+=put(90+i*cellA+cellA/2,50,eA,54);for(let i=0;i<nB;i++)b+=put(90+i*cellB+cellB/2,126,eB,54);return svg(w,h,b,alt,800)}function tree(x,y,s,apples){const LEAF="#7FC08A",st=`stroke="${INK}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"`;const canopy=a=>`<circle cx="-64" cy="-168" r="70" fill="${LEAF}" ${a}/><circle cx="64" cy="-168" r="70" fill="${LEAF}" ${a}/><circle cx="0" cy="-222" r="82" fill="${LEAF}" ${a}/><circle cx="0" cy="-150" r="70" fill="${LEAF}" ${a}/>`;let b=`<g transform="translate(${x},${y}) scale(${s})"><rect x="-17" y="-125" width="34" height="125" rx="13" fill="#C08A5E" ${st}/>`+canopy(st)+canopy(`stroke="none"`)+faceAt(0,-110,1.3,13,5);(apples||[]).forEach(a=>{b+=`<circle cx="${a[0]}" cy="${a[1]}" r="${a[2]||13}" fill="#F4796F" stroke="#C4564C" stroke-width="3.2"/>`});return b+`</g>`}function ladder(x1,y1,x2,y2,wd){const rail=`M${x1} ${y1} L${x2} ${y2} M${x1+wd} ${y1} L${x2+wd} ${y2}`;let rung="";for(let i=1;i<=5;i++){const k2=i/6,xx=x1+(x2-x1)*k2,yy=y1+(y2-y1)*k2;rung+=`M${xx} ${yy} H${xx+wd}`}const ln=(d,c,w)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;const at=t=>[x1+(x2-x1)*t,y1+(y2-y1)*t];const a=at(2/6),b=at(3/6),g=at(2.5/6);const plate=`<polygon points="${a[0]},${a[1]} ${a[0]+wd},${a[1]} ${b[0]+wd},${b[1]} ${b[0]},${b[1]}" fill="#E0B07A"/>`;const k=Math.min((wd-12)/45,(Math.abs(y2-y1)/6-10)/17.6);return plate+ln(rail,INK,12)+ln(rung,INK,10)+ln(rail,"#E0B07A",7)+ln(rung,"#E0B07A",5.5)+faceAt(g[0]+wd/2,g[1]-4.4*k,k,9,4)}function basketIcon(x,y,s){const W=s,H=s*220/211;return`<image href='data:image/webp;base64,' x='${(x-W/2).toFixed(1)}' y='${(y-H/2).toFixed(1)}' width='${W.toFixed(1)}' height='${H.toFixed(1)}'/>`}function basketSvg(x,y){const st=`stroke="${INK}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"`;return`<path d="M${x-60} ${y+8} H${x+60} Q${x+56} ${y+58} ${x+44} ${y+78} Q${x+39} ${y+86} ${x+28} ${y+86} H${x-28} Q${x-39} ${y+86} ${x-44} ${y+78} Q${x-56} ${y+58} ${x-60} ${y+8} Z" fill="#E8BE86" ${st}/><path d="M${x-55} ${y+30} H${x+55} M${x-37} ${y+79} H${x+37}" fill="none" stroke="#C99A64" stroke-width="4.5" stroke-linecap="round"/><rect x="${x-67}" y="${y}" width="134" height="16" rx="8" fill="#D9A26A" ${st}/>`+faceAt(x,y+52,1.4,15,5)}function pennyScene(){return svg(900,600,`<image href="data:image/webp;base64," x="0" y="0" width="900" height="600"/>`,"Four pictures. One: a pig looks at a red apple at the top of a tree, and thinks about it. Two: the wind blows and shakes the tree, and the apple wobbles. Three: the apple drops with a plop into a basket under the tree. Four: the pig sits and eats the apple.")}function orchardScene(){return svg(900,600,`<image href="data:image/webp;base64," x="0" y="0" width="900" height="600"/>`,"An orchard with an apple tree, a bird in the tree, a ladder, a basket of apples, a bee flying over the basket, a fence, a deer behind the fence, and a chick in front of the fence")}function signShapes(){const st=`stroke="${INK}" stroke-width="5" stroke-linejoin="round"`;const b=`<rect x="30" y="20" width="100" height="210" fill="${COL.orange}" ${st} stroke-linejoin="miter"/><circle cx="262" cy="125" r="82" fill="${COL.green}" ${st}/><polygon points="400,42 562,42 481,212" fill="${COL.red}" ${st}/><rect x="632" y="52" width="146" height="146" fill="${COL.blue}" ${st} stroke-linejoin="miter"/><rect x="832" y="84" width="178" height="82" fill="${COL.yellow}" ${st} stroke-linejoin="miter"/>`;return svg(1040,250,b,"An orange rectangle, a green circle, a red triangle, a blue square, and a yellow rectangle")}const PICKS=[[X.apple,5],[X.gapple,7],[X.pear,3]];function chartFig(){const cell=84,lab=124,cols=8,w=lab+cols*cell+8,h=PICKS.length*cell+8;let b="";PICKS.forEach((r,ri)=>{const y=4+ri*cell;b+=`<rect x="4" y="${y}" width="${lab}" height="${cell}" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="3"/>`+em(4+lab/2,y+cell/2,r[0],60);for(let c=0;c<cols;c++){b+=`<rect x="${4+lab+c*cell}" y="${y}" width="${cell}" height="${cell}" fill="var(--surface)" stroke="var(--ink)" stroke-width="2"/>`;if(c<r[1])b+=em(4+lab+c*cell+cell/2,y+cell/2,X.hand,46)}});return svg(w,h,b,"Picture chart with a red apple row, a green apple row, and a pear row. Each hand is one pick.")}function signPaper(){const b=`<rect x="108" y="170" width="24" height="86" rx="11" fill="#C08A5E" stroke="${INK}" stroke-width="3.4"/><rect x="8" y="8" width="224" height="166" rx="22" fill="#FFFFFF" stroke="${INK}" stroke-width="5"/><rect x="78" y="24" width="84" height="74" rx="14" fill="none" stroke="#A98A7A" stroke-width="4" stroke-dasharray="3 9" stroke-linecap="round"/><path d="M32 142 H208" fill="none" stroke="#A98A7A" stroke-width="4" stroke-dasharray="10 8" stroke-linecap="round"/>`;return svg(240,260,b,"A blank sign with a spot for a drawing and a line for writing")}function mysteryBasket(){return svg(420,280,`<image href='data:image/webp;base64,' x='43' y='6' width='333' height='265'/>`,"A picnic basket with a red checked cloth over the top")}function ratherFig(){const pick=svg(300,260,frame(300,260)+`<image href='data:image/webp;base64,' x='56' y='20' width='188' height='220'/>`,"A ladder leaning on an apple tree");const cake=svg(300,260,frame(300,260)+em(150,130,X.cake,170),"A cake");return`<div class="figure" style="align-items:center">${pick}<span class="big">or</span>${cake}</div>`}function standFig(){const w=900,h=380,st=`stroke="${INK}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"`;let b=frame(w,h)+`<path d="M5 330 H895" stroke="var(--line)" stroke-width="4"/>`;b+=`<circle cx="250" cy="80" r="52" fill="#FBF6EF" ${st}/>`+faceAt(250,100,1.05,12,4.5)+`<path d="M250 80 V46 M250 80 H274" fill="none" stroke="${INK}" stroke-width="5" stroke-linecap="round"/>`;b+=`<rect x="170" y="160" width="160" height="160" rx="18" fill="${COL.blue}" ${st}/><path d="M250 160 V320 M170 240 H330" fill="none" stroke="${INK}" stroke-width="4"/>`+faceAt(210,277,1.05,11,4.5);b+=`<rect x="470" y="100" width="150" height="230" rx="22" fill="#D9A26A" ${st}/><circle cx="598" cy="222" r="8" fill="${INK}"/>`+faceAt(537,165,1.15,13,5);b+=basketIcon(545,318,92);return svg(w,h,b,"A wall with a round clock above a square window, a door, and a basket in front of the door")}const SORTSET=[["R","B"],["G","S"],["G","B"],["R","S"],["G","B"],["R","S"],["R","B"],["G","S"]];function trayFig(){const w=880,h=250,cell=200;let b=frame(w,h)+`<rect x="30" y="28" width="${w-60}" height="${h-56}" rx="18" fill="#F6E7CF" stroke="${INK}" stroke-width="4"/>`;SORTSET.forEach((a,i)=>{const cx=52+i%4*cell+cell/2,cy=i<4?90:176;b+=em(cx,cy,a[0]==="R"?X.apple:X.gapple,a[1]==="B"?68:42)});return svg(w,h,b,"A tray of eight apples. Some are red and some are green. Some are big and some are small.")}function patRow(t,list){const cell=96,w=70+list.length*cell+40,h=120;let b=frame(w,h)+tag(38,h/2,t);list.forEach((e,i)=>{b+=put(70+i*cell+cell/2,h/2,e,60)});b+=`<text x="${70+list.length*cell+16}" y="${h/2+2}" font-size="44" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="var(--muted)">?</text>`;return svg(w,h,b,"A row of pictures that repeat, ending with a question mark",w>900?900:w)}const TREELINE=[[.45,"A",90],[.3,"B",220],[.5,"C",350],[.35,"D",480],[.4,"E",610]];function treeLineFig(){const w=700,h=230,base=180;let b=frame(w,h)+`<path d="M24 ${base} H${w-24}" stroke="var(--line)" stroke-width="4"/>`;TREELINE.forEach(t=>{b+=tree(t[2],base,t[0],[[-60,-170],[55,-195],[0,-250]])});TREELINE.forEach(t=>{b+=tag(t[2],204,t[1])});return svg(w,h,b,"Five apple trees of different heights standing on one line, lettered A, B, C, D and E")}const PENNY="Penny the pig wanted the big red apple at the very top of the tree. First, she jumped as high as she could, but the apple was too high. Next, she pushed a basket under the tree and stood on top of it, but she still could not reach. <strong>(Stop here. Ask what will happen next.)</strong> Just then, a strong wind shook the tree. Plop! The apple fell right into the basket, and Penny ate it for lunch.";const GROWS="Every apple starts out as a flower. In the spring, an apple tree is covered with white flowers. A bee lands on a flower to drink. Yellow dust called pollen sticks to the bee's legs. The bee carries that pollen to the next flower, and that is the job the flower was waiting for. Then the petals fall off and a tiny green apple starts to grow where the flower was. The apple grows all summer long. By fall it is big and red and ready to pick.";const LETTERS=["P","C","L","H","D","N","F","W","G","J","c","p","w","k"];const NUMS=["2","4","1","5","3","7","10","8","6","9"];const SAY="Listen to your teacher. Say your answer out loud.";const FIND12=["S","a","B","e","M","o","R","u","V","y","T","q"];function findLetterFig(){const cell=152,per=6,w=per*cell+40,h=348;let b=frame(w,h);FIND12.forEach((L,i)=>{const cx=20+i%per*cell+cell/2,cy=26+Math.floor(i/per)*168;b+=`<rect x="${cx-56}" y="${cy}" width="112" height="128" rx="20" fill="#FBF1E4" stroke="${INK}" stroke-width="4"/>`;b+=window.TP_LETTER_CARD(L,cx,cy)});return svg(w,h,b,"Twelve cards laid out in two rows of six. Each card has one printed letter on it.")}const BENCH_SAMPLE="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself.";const BENCH_DECK="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of any deck. A child sitting exactly at that goal still lands near 60 percent of whatever sample you show, and the suggested rating reads that as approaching. Set the rating yourself against those two counts.";const BENCH_FULL="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. The two inventories are scored under one code, so a child right at goal lands near 33 of 52 and the suggested rating reads that as approaching. Hold the uppercase count and the lowercase count against the two numbers above and set the rating yourself.";const ALPHA_FULL=E.alphabet({std:["TK.ELA.FLS.2.4"],sounds:false}).map(p=>Object.assign({},p,{key:p.key.concat([BENCH_FULL])}));const STOPS=[{id:1,title:"Apple Tree Letters",short:"Letters",parts:[{title:"Find the Letter",std:["TK.ELA.FLS.2.4"],n:10,dur:90,dir:"Listen to your teacher. Point to the letter on your screen.",desc:"matching a spoken letter name to its printed form (12 cards, 6 uppercase and 6 lowercase)",fig:()=>F.row(findLetterFig()),key:["Say: Here are twelve letter cards from the apple stand. I will say a letter name. Point to the card with that letter.","Say: Point to the letter e. (top row, fourth card)","Say: Point to the letter M. (top row, fifth card)","Say: Point to the letter a. (top row, second card)","Say: Point to the letter q. (bottom row, sixth card)","Say: Point to the letter R. (bottom row, first card)","Say: Point to the letter y. (bottom row, fourth card)","Say: Point to the letter S. (top row, first card)","Say: Point to the letter u. (bottom row, second card)","Say: Point to the letter T. (bottom row, fifth card)","Say: Point to the letter B. (top row, third card)","The top row reads S, a, B, e, M, o and the bottom row reads R, u, V, y, T, q. Six cards are uppercase and six are lowercase, and two of the twelve are never asked for.","This is the direction the standard asks for: the child hears a name and finds the printed letter. Keep the uppercase and the lowercase results apart in your notes.","a, e and o are all small and round, and u and y share the same bowl shape. Those are the ones to watch. If the child points to the wrong one of a group, write down which one.","End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself."]},{title:"Name the Letter",std:["TK.ELA.FLS.2.4"],kind:"words",full:ALPHA_FULL,words:LETTERS,unit:"Letter",n:14,dur:90,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters (10 uppercase, 4 lowercase)",key:["Say: Let's pick letters off the apple tree. Tell me the name of each letter. Click Next after each one.","Correct means the child says the letter name. If the child gives the sound, ask once: What is the name of this letter?","The first 10 are uppercase (P C L H D N F W G J). The last 4 are lowercase (c p w k). Write down the ones missed.","These are different letters from the LP 1 game. Use both lists together to see how many letter names the child knows so far.","If the child misses 4 in a row, stop and change the number tried.","Find the Letter at the top of this stop is the part this standard is written for. The standard asks the child to match a spoken name to its printed form, and naming a letter on sight is harder than that, so rate this standard on the Find the Letter count and keep this deck as the extra note.",BENCH_DECK]}]},{id:2,title:"Apple Picking Count",short:"Count",parts:[{title:"Count the Rows",std:["TK.MATH.1.2"],n:6,dur:135,dir:"First count some small things from near you. Then count the pictures on the screen.",desc:"counting 10 or more real objects one by one where the teacher can see, then counting rows of 10, 12, 13, and 14 objects one by one on the screen",fig:()=>F.row(countPanel([[X.apple,10,10,84,58],["BASKET",12,6,84,58],[X.honey,13,7,74,52],[X.flower,14,7,84,58]],"Four groups to count: red apples, baskets, honey jars, and flowers")),key:["Start with real things, before the screen. Say: Go and get ten small things you can hold, like spoons, blocks, socks or crayons, and set them on the table where I can see them. Then say: Move each one over to the side as you count it out loud. (One number word for each thing moved, no skips and no double counts. Moving each object is what makes the matching visible to you, so watch the hands as well as the numbers.)","Say: Push them back into a pile, add a few more, and count the whole lot again the same way. (Any number past ten. The goal is 10 or more with one number word for each object. If the count breaks down partway, write down the number it broke at.)","Those first two counts are the evidence for this standard, because they are the ones you can see for yourself. The screen rows below are still worth doing and they show whether a count holds together over bigger groups, but the child is pointing at a monitor you cannot see, so do not rate this standard on them alone and do not rate it on what an adult in the room reports.","Row 1. Say: Point to each red apple and count out loud. (10 apples) Look for one number word for each apple, with no skips and no double counts.","Row 2. Say: Now count the baskets. There are two lines of them. (12 baskets, in lines of 6 and 6)","Row 3. Say: Now count the honey jars. There are two lines of them. (13 honey jars, in lines of 7 and 6)","Row 4. Say: Now count the flowers. There are two lines of them. (14 flowers, in lines of 7 and 7)","Count an item correct only when the last number said matches the number of objects. On the screen rows, have the child say the numbers slowly enough that you can hear one number word for each picture, and watch the child's eyes move along the row. Where you cannot tell, leave the row out of the count rather than taking an adult's word for it.","Note where the count broke down: skipped a number, counted one twice, or lost track after 10."]},{title:"Mixed Up Count",std:["TK.MATH.1.2"],n:4,dur:75,dir:"These are all mixed up. Count each group out loud.",desc:"counting mixed-up groups of 10, 11, 12, and 13 objects one by one",fig:()=>grid2(scatter(1,X.ladybug,10,5,"A group of ladybugs",400),scatter(2,X.bee,11,19,"A group of bees",400),scatter(3,X.pear,12,31,"A group of pears",400),scatter(4,X.gapple,13,43,"A group of green apples",400)),key:["Box 1. Say: These are not in a row. Count the ladybugs. (10 ladybugs)","Box 2. Say: Count the bees. (11 bees)","Box 3. Say: Count the pears. (12 pears)","Box 4. Say: Count the green apples. (13 green apples)","Mixed-up groups are harder than rows because the child has to keep track of which ones are already counted. Look for a plan, like going across each line or touching each one on the screen.","You can also have the child count 10 or more small things at home, like blocks or crayons, moving each one as it is counted."]}]},{id:3,title:"Busy Bee Sounds",short:"Sounds",parts:[{title:"Buzz the First Sound",std:["TK.ELA.FLS.2.1"],n:4,dur:50,dir:"Listen to your teacher. Say the first sound.",desc:"saying the first sound of a pictured word",fig:()=>F.row(cards([X.cake,X.leaf,X.honey,X.duck],{cell:170,size:100,alt:"Cake, leaf, honey, duck"})),key:["Model first: Cider. The first sound in cider is /s/. Now you try.","Point to the cake. Say: Cake. What is the first sound in cake? (/k/)","Point to the leaf. Say: Leaf. What is the first sound in leaf? (/l/)","Point to the honey. Say: Honey. What is the first sound in honey? (/h/)","Point to the duck. Say: Duck. What is the first sound in duck? (/d/)","The answer is the sound, not the letter name. If the child says a letter name, ask: What sound do you hear first?"]},{title:"Rhyme Buzz",std:["TK.ELA.FLS.2.3"],n:3,dur:55,dir:"Listen to your teacher. Say a word that rhymes.",desc:"making a rhyme for a given word",fig:()=>F.row(cards([X.hen,"caterpillar",X.sheep],{cell:170,size:100,alt:"Hen, bug, sheep"})),key:["Model first: Pie, sky, my. They rhyme. They sound the same at the end.","Point to the hen. Say: Tell me a word that rhymes with hen. (ten, pen, men, when, zen, len)","Point to the bug. Say: Tell me a word that rhymes with bug. (rug, hug, mug, dug, zug)","Point to the sheep. Say: Tell me a word that rhymes with sheep. (jeep, beep, deep, keep, sleep, meep)","Real words and silly words both count. A rhyme that is close but not perfect counts too."]},{title:"Put the Parts Together",std:["TK.ELA.FLS.2.2"],n:4,dur:45,dir:"Listen to the slow buzzy voice. Say the whole word.",desc:"blending syllables and single sounds into a word with picture support",fig:()=>F.row(cards([X.apple,"BASKET",X.tractor,X.pig],{cell:170,size:100,alt:"An apple, a basket, a tractor, a pig"})),key:["Say: The bee talks very slowly. Put the parts together and tell me the word. The pictures can help you.","Say with a pause in the middle: ap ... ple. (apple)","Say: bas ... ket. (basket)","Say: trac ... tor. (tractor)","Say the three sounds one at a time: /p/ ... /i/ ... /g/. (pig)","The first three are syllables and the last one is single sounds, which is harder. Note which kind the child can blend."]}]},{id:4,title:"Number Baskets",short:"Numbers",parts:[{title:"Basket Numbers",std:["TK.MATH.1.5"],kind:"words",words:NUMS,unit:"Number",noCount:true,n:10,dur:45,dir:"Say the name of each number.",desc:"naming the numerals 1 to 10",key:["Say: Each basket has a number on it. What number is this? Click Next after each one.","The order is 2, 4, 1, 5, 3, 7, 10, 8, 6, 9. Correct means the child says the number name. Write down the ones missed.","Watch for 6 and 9 mixed up. They come one after the other at the end.","If the child counts up on fingers to find the name, note it. The goal is to know each numeral on sight."]},{title:"Which Has More?",std:["TK.MATH.1.6"],n:4,dur:65,dir:"Look at the pictures. Answer out loud.",desc:"comparing two groups by counting (more, same, fewer)",fig:()=>col(cmpPanel(1,X.apple,6,90,X.pear,2,90,"A row of red apples above a row of pears"),cmpPanel(2,X.bee,3,90,X.flower,5,90,"A row of bees above a row of flowers"),cmpPanel(3,"BASKET",7,104,X.gapple,7,70,"A row of baskets above a row of green apples"),cmpPanel(4,X.honey,9,62,X.tree,8,94,"A row of honey jars above a row of trees")),key:["Box 1. Say: Are there more apples or more pears? How do you know? (More apples. 6 apples and 2 pears.)","Box 2. Say: Which group has fewer, the bees or the flowers? (Fewer bees. 3 bees and 5 flowers.)","Box 3. Say: Are there more baskets, more green apples, or the same number of each? (The same. 7 baskets and 7 green apples. The baskets are spread out, so their row looks longer.)","Box 4. Say: Are there more honey jars or more trees? (More honey jars. 9 honey jars and 8 trees. The trees are spread out, so their row looks longer.)","Look for counting, not guessing from how long the row is. Listen for the words more, same, fewer, or less."]}]},{id:5,title:"Penny and the Apple",short:"Story",parts:[{std:["TK.ELA.R.3.2"],n:4,dur:100,read:PENNY,dir:"Listen to the story. Then answer out loud.",desc:"questions about the character, the order of events, and what happens next in a story read aloud",fig:()=>F.row(pennyScene()),key:["Read the story out loud. Stop after the third sentence, when Penny still cannot reach.","Ask at the stopping place: What do you think will happen next? (Any guess that fits the story, like Penny gets a ladder, shakes the tree, asks a friend for help, or the apple falls.) Then read the rest.","Ask: Who is this story about? What did she want? (Penny the pig. The big red apple at the top of the tree.)","Ask: What did Penny try first? What did she try after that? (First she jumped. Then she stood on a basket.) Count it correct when the two tries are in the right order.","Ask: How did Penny get the apple at the end? (The wind shook the tree and the apple fell into the basket.)","If picture supports are on, the picture on the screen can help the child remember."]}]},{id:6,title:"Farm Stand",short:"Farm Stand",parts:[{title:"Sign Shapes",std:["TK.MATH.4.1"],n:6,dur:70,dir:"Look at the signs. Answer out loud. Then draw one on your paper.",desc:"naming, describing, and drawing circles, squares, rectangles, and triangles",fig:()=>F.row(signShapes()),key:["Say: The farm stand has signs in lots of shapes. What shape is the green sign? (circle)","Say: What shape is the red sign? (triangle. It still counts as a triangle when the point is at the bottom.)","Say: What shape is the blue sign? (square)","Say: Two of the signs are long rectangles. One is tall and one is wide. Which colors are they? (orange and yellow. The blue sign is a square, so it does not belong here, even though a square is also a kind of rectangle.)","Say: Tell me about the red triangle. How many sides does it have? How many corners? (3 sides and 3 corners. Words like straight or pointy are a plus.)","Say: Draw a square on your paper. Hold it up. (A closed shape with 4 sides and 4 corners. The sides are about the same length. It does not need to be neat.)"]},{title:"Orchard Hide and Seek",std:["TK.MATH.4.5"],n:6,dur:60,dir:"Look at the picture. Answer out loud.",desc:"position words (in, over, next to, behind, in front of)",fig:()=>F.row(orchardScene()),key:["Say: Where is the bird? (In the tree, or up in the tree. Look for a position word, not only pointing.)","Say: What is in the basket? (apples)","Say: What is flying over the basket? (the bee)","Say: What is right next to the tree, the ladder or the fence? (the ladder)","Say: Is the deer in front of the fence or behind the fence? (behind)","Say: What is in front of the fence? (the chick, and little bird or baby chicken is fine too)"]}]},{id:7,title:"Sign Painters",short:"Write",parts:[{title:"First Letter",std:["TK.ELA.W.4.2"],n:3,dur:80,dir:"Listen for the sound. Write the letter on your paper and hold it up.",desc:"writing the letter for a beginning sound (b, p, f)",fig:()=>F.row(cards([X.bee,X.pear,X.fox],{cell:180,size:110,alt:"Bee, pear, fox"})),key:["Point to the bee. Say: Bee starts with /b/. Write the letter that makes the /b/ sound. Hold it up. (b or B)","Point to the pear. Say: Pear starts with /p/. Write the letter for /p/. (p or P)","Point to the fox. Say: Fox starts with /f/. Write the letter for /f/. (f or F)","A letter counts when you can tell what it is. Backward or wobbly letters still count. Uppercase or lowercase is fine.","You give the sound. The child picks and writes the letter. If an adult names the letter for the child, do not count that one."]},{title:"Farm Stand Sign",std:["TK.ELA.W.4.4"],n:3,label:"checks met",dur:90,dir:"Draw something to sell at the farm stand. Write letters to tell what it is. Hold it up.",desc:"writing letters to label a drawing",fig:()=>`<div class="figure" style="align-items:center">${F.pic(X.pencil,"","6rem")}${signPaper()}${F.pic(X.apple,"","6rem")}</div>`,key:["Say: Let's make a sign for the farm stand. Draw one thing you would sell, like apples, pie, or honey. Then write a word or some letters to tell what it is. Hold it up and tell me what you wrote.","Look for: writing that is separate from the drawing (letters or marks that look like letters, not only a picture).","Look for: 2 or more letters you can recognize. They do not need to spell the word.","Look for: the child tells you what the writing says, like It says pie. This shows the letters stand for a word or an idea.","If the child writes only a name, that is a fine start. Ask: What does it say? Then ask for some letters about the thing for sale too."]}]},{id:8,title:"Apple Vote",short:"Chart",parts:[{std:["TK.MATH.3.4"],n:5,dur:90,dir:"Look at the chart. Answer out loud. Then make marks on your paper.",desc:"reading, copying, and adding to a picture chart with three groups",fig:()=>F.row(chartFig()),key:["Say: Some children picked the fruit they like best: a red apple, a green apple, or a pear. Each hand is one child. How many children picked the red apple? (5)","Say: Which fruit got the most picks? (The green apple. It has 7.)","Say: Which fruit got the fewest picks? (The pear. It has 3.)","Say: On your paper, make one mark for each child who picked the pear. Hold it up. (3 marks, one for each hand in the pear row)","Say: Two more children pick the red apple. What should we add to the chart? (Two more hands in the red apple row, because each hand is one child. That makes 7.)"]}]},{id:9,title:"Cider Chat",short:"Chat",parts:[{title:"What Is It?",std:["TK.ELA.L.1.1"],n:6,dur:60,dir:"Look at each picture. Answer out loud.",desc:"naming objects, actions, and describing words from pictures",fig:()=>F.row(cards(["BASKET",X.butterfly,X.tractor,"ACT:dance","ACT:bike",X.apple],{cell:150,size:92,num:true,alt:"Basket, butterfly, tractor, a person dancing, a person riding a bike, an apple"})),key:["Picture 1. Say: What is this? (basket)","Picture 2. Say: What is this? (butterfly)","Picture 3. Say: What is this? (tractor. This is a harder word.)","Picture 4. Say: What is this person doing? (dancing)","Picture 5. Say: What is this person doing? (riding a bike, or biking)","Picture 6. Say: This is an apple. Tell me two words about what an apple is like. (Describing words such as red, round, sweet, crunchy, juicy, shiny, smooth.)","Pictures 1 to 3 are naming words, 4 and 5 are action words, and 6 is describing words. Note which kind was hard."]},{title:"Mystery Basket",std:["TK.ELA.LS.1.5"],n:3,label:"checks met",dur:75,dir:"Something is hiding in the basket. Ask your teacher questions to find out what it is.",desc:"asking questions and follow-up questions to find out information",fig:()=>F.row(mysteryBasket()),key:["Your secret: a rabbit is hiding in the basket. Do not tell.","Say: Something is hiding in my basket. Ask me questions to find out what it is. You can ask things like: Is it a food? What does it feel like?","Answer each question in a few words: It is an animal. It is soft. It has long ears. It hops. It likes to eat carrots.","Look for: asks a real question to get information (not only a guess, like An apple!).","Look for: asks a follow-up question that builds on your answer (after It is an animal, asks Does it fly? or How big is it?).","Look for: checks the idea with a question at the end (Is it a rabbit? Is it a bunny?). If the child is stuck after 4 or 5 questions, give one more clue."]},{title:"Pick One",std:["TK.ELA.LS.1.7"],n:3,label:"checks met",dur:60,dir:"Pick one. Tell your teacher why.",desc:"sharing an opinion with a reason and details",fig:()=>ratherFig(),key:["Say: Would you rather climb the ladder and pick apples, or bake an apple cake? Tell me which one and why.","Look for: tells an opinion (picks one).","Look for: gives a reason that explains the pick. If there is no reason, ask once: Why?","Say: Tell me more. What would you do first? What would you need? Look for: 2 or more details in the description."]}]},{id:10,title:"Sorting Table",short:"Sorting",parts:[{title:"Sort the Apples",std:["TK.MATH.2.5"],n:3,dur:60,dir:"Look at the tray of apples. Answer out loud.",desc:"sorting eight objects by color, by size, and by two attributes at once",fig:()=>F.row(trayFig()),key:["Say: Eight apples came in from the orchard on this tray. Sort them by color in your head. How many red? How many green? (4 red and 4 green)","Say: Now forget the color. Sort them by size. How many big? How many small? (4 big and 4 small)","Say: Now two things at once. Find the apples that are red AND big. How many are there? (2)","Sorting by two things at once is the hard part. If the child can sort by color and by size but not both together, write that down: one attribute is there and two is not yet.","The child may also point and move a finger along the tray. Touching each apple while sorting is fine and is worth noting."]},{title:"What Comes Next?",std:["TK.MATH.2.6"],n:3,dur:60,dir:"Look at each row. Say what comes next.",desc:"extending three repeating patterns and naming the part that repeats",fig:()=>col(patRow(1,[X.apple,X.leaf,X.apple,X.leaf,X.apple,X.leaf,X.apple]),patRow(2,[X.apple,X.apple,X.pear,X.pear,X.apple,X.apple,X.pear,X.pear]),patRow(3,["BASKET",X.bee,X.flower,"BASKET",X.bee,X.flower,"BASKET"])),key:["Row 1. Say: Apple, leaf, apple, leaf, apple, leaf, apple. What comes next? (a leaf)","Row 2. Say: Look at this row. What comes next? (an apple. The pattern is apple, apple, pear, pear, and the row ends with the second pear.)","Row 3. Say: What comes next here? (a bee. The pattern is basket, bee, flower, and the row ends with a basket.)","Go back to row 1. Say: What part keeps repeating over and over? (apple, leaf)","Row 2 and row 3 are harder than row 1 because the repeating part is two long and three long. Note which rows the child could finish."]},{title:"Tree Line",std:["TK.MATH.3.2"],n:3,dur:45,dir:"Look at the five trees. Answer out loud.",desc:"ordering five objects by height",fig:()=>F.row(treeLineFig()),key:["Point to the trees. Say: Five apple trees grow in a row at the orchard. Which tree is the tallest? (C)","Say: Which tree is the shortest? (B)","Say: Now put all five trees in order, from the shortest one to the tallest one. (B, D, E, A, C) Count it correct only when all five are in the right order.","All five trees stand on the same line, so the child can compare the tops. If the child can pick the tallest and the shortest but cannot order the middle three, write that down: the comparing is there and the ordering is not yet."]}]},{id:11,title:"How an Apple Grows",short:"Apple Facts",parts:[{std:["TK.ELA.R.3.3"],n:3,dur:75,sup:true,read:GROWS,dir:"Listen to your teacher read about apple trees. Then answer out loud.",desc:"making an inference, making a connection, and asking a question about an informational text read aloud",fig:()=>F.row(cards([X.flower,X.bee,X.apple],{cell:180,size:110,num:true,alt:"A white flower, a bee, an apple"})),key:["If picture supports are on, point to the three pictures first. Say: This is the order an apple grows in. First a flower, then a bee, then an apple. Then read the facts out loud.","Ask: What if no bees at all came to the orchard in the spring? What do you think would happen? (Not many apples would grow, or no apples would grow. The facts never say this part, so the child has to put two of them together.)","Ask: Have you ever seen a bee on a flower, or watched a bug land on a plant? Tell me about it. (Any real answer from the child's own life counts.)","Say: What do you want to know about apple trees? Ask me a question. You can start with What, Where, or Why. (Asks a real question about trees, flowers, bees or apples. Telling a fact instead of asking is not a question.)"]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Letter Names",std:["RF.K.1"],needs:["TK.ELA.FLS.2.4"],n:5,dir:"Say the name of each letter.",html:()=>F.cards(["Q","V","Z","r","q"],{size:"5rem",min:130}),key:["Q (the name is cue)","V","Z (zee)","r, the lowercase letter. Watch for r and n mixed up.","q, the lowercase letter. Watch for q mixed up with p or g.","TK asks for many letter names. Kindergarten asks for all of the uppercase and lowercase letters, so these are 5 that TK children miss most often. The name is the answer here, not the sound."]},2:{id:"L2",lv:true,title:"Level Up: How Many?",std:["K.CC.B.4"],needs:["TK.MATH.1.2"],n:3,dir:"Count the apples. Then answer out loud.",html:()=>col(svg(796,96,frame(796,96)+Array.from({length:9},(_,i)=>em(20+i*84+42,48,X.gapple,58)).join(""),"A row of green apples"),scatter(0,X.gapple,9,57,"The same green apples, mixed up in a box",400)),key:["Say: Count the green apples in the row. How many are there? (9. Look for the child to say 9 as the answer to how many, without counting again. The last number said tells how many.)","Point to the box. Say: I moved the same apples into this box. I did not add any or take any away. How many apples are in the box? (9. The Kindergarten idea is that the number stays the same when things are moved around. Saying 9 without counting again shows it best.)","Say: If one more apple rolls into the box, how many will there be? (10. One more is the next number.)"]},3:{id:"L3",lv:true,title:"Level Up: Last Sounds",std:["RF.K.2"],needs:["TK.ELA.FLS.2.1"],n:4,dir:"Listen to your teacher. Say the last sound.",html:()=>F.row(cards([X.bus,X.cup,X.pan,X.dog],{cell:170,size:100,alt:"Bus, cup, pan, dog"})),key:["Model first: Pig. The last sound in pig is /g/. Then point to the bus. Say: Bus. What is the last sound in bus? (/s/)","Point to the cup. Say: Cup. What is the last sound in cup? (/p/)","Point to the pan. Say: Pan. What is the last sound in pan? (/n/)","Point to the dog. Say: Dog. What is the last sound in dog? (/g/)"]},6:{id:"L6",lv:true,title:"Level Up: Shapes All Around",std:["K.G.A.1"],needs:["TK.MATH.4.5"],n:5,dir:"Look at the farm stand wall. Answer out loud.",html:()=>F.row(standFig()),key:["Say: Find something shaped like a circle. What is it? (the clock)","Say: What shape is the door? (rectangle)","Say: Where is the clock? Use a word like above, below, or next to. (above the window)","Say: What is beside the window? (the door)","Say: What is in front of the door? (the basket)"]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=10;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}" style="font-size:1.6rem">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){let c=`<div class="tf-wrap"><div class="tf">`;for(let k=0;k<10;k++)c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`;return c+`</div></div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear. The top row is a five frame.</p>`}function abcHtml(){return`<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center">${"ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(c=>`<span style="border:2px solid var(--line);border-radius:10px;padding:2px 10px;font-family:var(--font-display);font-weight:800;font-size:1.7rem">${c}${c.toLowerCase()}</span>`).join("")}</div>`}const TOOLS={np:{name:"Number path 1 to 10",std:["TK.MATH.1.2","TK.MATH.1.6","K.CC.B.4"],html:npHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{npOn[x.dataset.n]=!npOn[x.dataset.n];r()})},tf:{name:"Ten frame",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.2.5","TK.MATH.3.4","K.CC.B.4"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},abc:{name:"Alphabet strip",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],html:abcHtml},talk:{name:"Talking starters",std:["TK.ELA.LS.1.7"],html:()=>`<ul class="starters"><li>I pick ____ because ____.</li><li>First I would ____.</li><li>I would need ____.</li></ul><p class="small">Say a starter out loud for the child to finish.</p>`}};const SUP_CAVEATS=[{t:"np",std:["TK.MATH.1.5"],msg:"The number path shows the numerals in order. If it was open during Basket Numbers, the child may have counted along the path to find a name. That is not the same as knowing the numeral on sight."},{t:"np",std:["TK.MATH.1.2","K.CC.B.4"],msg:"The number path helps the child keep the counting order. Note that the count was done with a visual."},{t:"tf",std:["TK.MATH.1.6"],msg:"If you matched the two groups on the ten frame, the child compared with a model you built. Note that the comparing was supported."},{t:"tf",std:["TK.MATH.2.5"],msg:"If the ten frame was used to park each sorted group, the child sorted into boxes you set up rather than making the groups alone. Note it."},{t:"abc",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],msg:"With the alphabet strip the child can find a letter and copy it. That still fits the standard, but note whether the child picked the right letter for the sound without help."},{t:"talk",std:["TK.ELA.LS.1.7"],msg:"The talking starter supplies the word because. Count the reason check as supported."},{t:"scribe",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],msg:"If an adult wrote the letters or guided the child's hand, those letters do not count as the child's writing."},{t:"adult",msg:"If the adult at home gave a hint or the answer, do not count that item as correct on the child's own."},{t:"objects",std:["TK.MATH.1.2"],msg:"Counting real objects at home is a fine way to show this standard. Note what the child counted and how many."},{t:"objects",std:["TK.MATH.2.5","TK.MATH.2.6","TK.MATH.3.2"],msg:"Sorting, patterning or lining up real objects at home is a fine way to show this standard. Note what the child used and how many."}];function stopLogs(st){const math=st.std.some(c=>/^TK\.MATH|^K\./.test(c)),write=st.std.some(c=>/\.W\.4\./.test(c)),out=["repeat","adult"];if(math)out.push("objects");out.push("time");if(write)out.push("scribe");out.push("brk");return out}return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:[],stopLogs,logNames:{adult:"Adult at home helped"}}}});
